events_list.input:
{
 "command": "find /workspace -maxdepth 4 -iname \"*health*\" -o -iname \"*healthcheck*\" 2>/dev/null | grep -v node_modules",
 "description": "Search for health-check related files"
}

{
 "command": "ls -la /workspace; ls -la /workspace/scripts",
 "description": "List repo root and scripts directory"
}

{
 "command": "bash --version | head -1; which bash curl; bash -c 'unset x; : \"${x:?boom}\"; echo \"exit=$?\"' ; echo \"---\"; bash -c '{ : \"${x:?boom}\"; }; echo after $?'",
 "description": "Check bash/curl availability and parameter-expansion error exit code"
}

{
 "command": "bash -c 'x=; : \"${x:?boom}\"; echo \"reached\"' ; echo \"exit=$?\"",
 "description": "Check exit code when required parameter is unset"
}

{
 "command": "chmod +x /workspace/tests/health_check_test.sh && /workspace/tests/health_check_test.sh; echo \"runner exit=$?\"",
 "description": "Make test script executable and run it"
}

{
 "command": "git status 2>&1 || echo \"not a git repo\"; echo \"---\"; git diff scripts/health_check.sh 2>&1; md5sum scripts/health_check.sh",
 "description": "Confirm production script is unchanged"
}

{
 "command": "/workspace/tests/health_check_test.sh 2>&1; echo \"exit=$?\"",
 "description": "Re-run full test suite to confirm final results"
}

{
 "command": "source /workspace/config/local-service.env && /workspace/scripts/health_check.sh \"$HEALTH_CHECK_URL\"; echo \"exit=$?\"",
 "description": "Run health check utility against configured local service"
}
